package com.taskflow.fixflow;
import java.util.*;import java.net.URI;import java.time.Instant;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.PageRequest;import com.taskflow.entity.TicketStatus;
@Service @Transactional public class PartRequestService {
 public record Input(@NotBlank @Size(max=120)String name,@Min(1) @Max(99)int quantity,@NotBlank @Size(max=2000)String purpose,@Size(max=1000)String referenceUrl){}
 public record Revision(@NotNull @PositiveOrZero Long version){}
 public record Reply(@NotNull @PositiveOrZero Long version,@NotNull String status,@NotBlank @Size(max=2000)String reply){}
 private final PartRequestRepository requests;private final MemberService members;private final TicketService tickets;private final NotificationService notifications;
 public PartRequestService(PartRequestRepository requests,MemberService members,TicketService tickets,NotificationService notifications){this.requests=requests;this.members=members;this.tickets=tickets;this.notifications=notifications;}
 public Map<String,Object> create(Long id,User actor,Input input){Ticket ticket=members.requireOwned(id,actor,true);if(!List.of(TicketStatus.OPEN,TicketStatus.ASSIGNED,TicketStatus.IN_PROGRESS).contains(ticket.status))throw new ApiException(409,"此工單已進入驗收或已結束，無法新增零件需求");String link=input.referenceUrl()==null?null:input.referenceUrl().strip();if(link!=null&&!link.isEmpty()){try{URI uri=URI.create(link);if(!List.of("http","https").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException();}catch(IllegalArgumentException ex){throw new ApiException(400,"參考連結僅接受有效 HTTP 或 HTTPS 網址");}}PartRequest p=new PartRequest();p.ticket=ticket;p.requestedBy=actor;p.name=input.name().strip();p.quantity=input.quantity();p.purpose=input.purpose().strip();p.referenceUrl=link;requests.saveAndFlush(p);tickets.log(ticket,actor,"提出零件需求："+p.name);notifications.partRequest(ticket,actor,p.id,false,"收到會員零件需求，請確認規格與相容性");return view(p);}
 public Map<String,Object> list(User actor,int page,int size){if(page<0||size<1||size>100)throw new ApiException(400,"分頁條件不正確");var result=requests.findByRequestedByIdOrderByIdDesc(actor.id,PageRequest.of(page,size));return Map.of("items",result.getContent().stream().map(this::view).toList(),"total",result.getTotalElements(),"totalPages",result.getTotalPages(),"page",page);}
 public List<Map<String,Object>> ticket(Long id,User actor,boolean member){if(member)members.requireOwned(id,actor,false);else tickets.find(id,actor,false);return requests.findByTicketIdOrderByIdDesc(id).stream().map(this::view).toList();}
 public Map<String,Object> update(Long id,User actor,Long version,String status,String reply){Long ticketId=requests.ticketId(id).orElseThrow(ApiException::missing);if(actor.role==Role.ADMIN)tickets.find(ticketId,actor,true);else members.requireOwned(ticketId,actor,true);PartRequest p=requests.lockById(id).orElseThrow(ApiException::missing);if(actor.role!=Role.ADMIN&&!p.requestedBy.getId().equals(actor.id))throw ApiException.missing();if(!Objects.equals(version,p.version)||!p.status.equals("PENDING"))throw new ApiException(409,"需求已更新，請重新載入確認");if(actor.role==Role.ADMIN){if(!List.of("REVIEWED","REJECTED").contains(status))throw new ApiException(400,"請選擇回覆狀態");p.reviewedBy=actor;p.reply=reply.strip();}else if(!status.equals("WITHDRAWN"))throw new ApiException(403,"僅可撤回自己的待確認需求");p.status=status;p.updatedAt=Instant.now();requests.saveAndFlush(p);tickets.log(p.ticket,actor,status.equals("WITHDRAWN")?"撤回零件需求："+p.name:"回覆零件需求："+p.name);if(actor.role==Role.ADMIN)notifications.partRequest(p.ticket,actor,p.id,true,"你的零件需求已有回覆");return view(p);}
 private Map<String,Object> view(PartRequest p){Map<String,Object> v=new LinkedHashMap<>();v.put("id",p.id);v.put("ticketId",p.ticket.getId());v.put("ticketNo",p.ticket.getTicketNo());v.put("name",p.name);v.put("quantity",p.quantity);v.put("purpose",p.purpose);v.put("referenceUrl",p.referenceUrl);v.put("status",p.status);v.put("reply",p.reply);v.put("version",p.version);v.put("createdAt",p.createdAt);v.put("updatedAt",p.updatedAt);return v;}
}
